import {
  KARDO_ICON_WIDTH,
  KARDO_LOGO_HEIGHT,
  KARDO_LOGO_WIDTH,
  kardoBrandColors,
  kardoIconOutlines,
  kardoLogoOutlines,
} from "./brand-paths";

/**
 * Official Kardo logo (2026-10-01 masters in Docs/Marca), outlines only, so
 * it looks the same on every system: the KARDO wordmark, whose O is the
 * symbol (a ring, a dot and two signal waves, the tap). The outlines live in
 * `brand-paths.ts`, generated by scripts/brand/build-brand.mjs.
 */
export type LogoTone = "light" | "dark" | "mono";

export type SymbolColors = {
  /** Ring and dot (and the letters in the full logo). */
  ring: string;
  /** Outer signal wave. */
  signal: string;
  /** Inner signal wave; defaults to `signal` drawn lighter. */
  signalSoft?: string;
};

const palettes: Record<LogoTone, SymbolColors> = {
  light: {
    ring: kardoBrandColors.light.ink,
    signal: kardoBrandColors.light.outer,
    signalSoft: kardoBrandColors.light.inner,
  },
  dark: {
    ring: kardoBrandColors.dark.ink,
    signal: kardoBrandColors.dark.outer,
    signalSoft: kardoBrandColors.dark.inner,
  },
  mono: { ring: "currentColor", signal: "currentColor" },
};

/** The symbol's box, for callers that place it inside another drawing. */
export const SYMBOL_WIDTH = KARDO_ICON_WIDTH;
export const SYMBOL_HEIGHT = KARDO_LOGO_HEIGHT;

/** Full logo as an SVG string (Open Graph image and other raw SVG uses). */
export function logoSvgMarkup(tone: Exclude<LogoTone, "mono">): string {
  const color = palettes[tone];
  const letters = kardoLogoOutlines.letters
    .map((d) => `<path fill="${color.ring}" d="${d}"/>`)
    .join("");
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${KARDO_LOGO_WIDTH} ${KARDO_LOGO_HEIGHT}">${letters}<path fill="${color.ring}" d="${kardoLogoOutlines.ring}"/><path fill="${color.ring}" d="${kardoLogoOutlines.dot}"/><path fill="${color.signal}" d="${kardoLogoOutlines.outer}"/><path fill="${color.signalSoft ?? color.signal}" d="${kardoLogoOutlines.inner}"/></svg>`;
}

export function Logo({
  tone = "light",
  className,
  title = "Kardo",
  style,
}: {
  tone?: LogoTone;
  className?: string;
  title?: string;
  style?: React.CSSProperties;
}) {
  const color = palettes[tone];
  return (
    <svg
      aria-label={title}
      className={className}
      role="img"
      style={{ height: "1.75rem", width: "auto", ...style }}
      viewBox={`0 0 ${KARDO_LOGO_WIDTH} ${KARDO_LOGO_HEIGHT}`}
      xmlns="http://www.w3.org/2000/svg"
    >
      {kardoLogoOutlines.letters.map((d) => (
        <path d={d} fill={color.ring} key={d.slice(0, 24)} />
      ))}
      <SymbolPaths color={color} outlines={kardoLogoOutlines} />
    </svg>
  );
}

/** The symbol alone, for tight spaces where the name is already present. */
export function LogoSymbol({
  tone = "light",
  className,
  decorative = false,
  style,
}: {
  tone?: LogoTone;
  className?: string;
  decorative?: boolean;
  style?: React.CSSProperties;
}) {
  const color = palettes[tone];
  return (
    <svg
      aria-hidden={decorative || undefined}
      aria-label={decorative ? undefined : "Kardo"}
      className={className}
      role={decorative ? undefined : "img"}
      style={{ height: "1.75rem", width: "auto", ...style }}
      viewBox={`0 0 ${KARDO_ICON_WIDTH} ${KARDO_LOGO_HEIGHT}`}
      xmlns="http://www.w3.org/2000/svg"
    >
      <SymbolPaths color={color} outlines={kardoIconOutlines} />
    </svg>
  );
}

/** The symbol as SVG shapes, for use inside another drawing; its box is
 * `SYMBOL_WIDTH` × `SYMBOL_HEIGHT` before `scale`. */
export function SymbolShapes({
  color,
  offsetX,
  offsetY,
  scale = 1,
}: {
  color: SymbolColors;
  offsetX: number;
  offsetY: number;
  scale?: number;
}) {
  return (
    <g transform={`translate(${offsetX} ${offsetY}) scale(${scale})`}>
      <SymbolPaths color={color} outlines={kardoIconOutlines} />
    </g>
  );
}

function SymbolPaths({
  color,
  outlines,
}: {
  color: SymbolColors;
  outlines: typeof kardoIconOutlines;
}) {
  return (
    <>
      <path d={outlines.ring} fill={color.ring} />
      <path d={outlines.dot} fill={color.ring} />
      <path d={outlines.outer} fill={color.signal} />
      <path
        d={outlines.inner}
        fill={color.signalSoft ?? color.signal}
        opacity={color.signalSoft ? undefined : 0.6}
      />
    </>
  );
}
